"use client";

import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { IconButton } from "@/components/ui/button";
import { SalesChannel } from "@/types";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useState, memo } from "react";
import {
  Store,
  Plus,
  Edit,
  Trash2,
  Eye,
  CheckCircle,
  XCircle,
  ShoppingBag,
  MessageCircle,
  Instagram,
  Globe,
} from "lucide-react";

const mockSalesChannels: SalesChannel[] = [
  {
    id: "1",
    name: "Shopee",
    description: "Penjualan melalui marketplace Shopee",
    status: true,
  },
  {
    id: "2",
    name: "Tokopedia",
    description: "Penjualan melalui marketplace Tokopedia",
    status: true,
  },
  {
    id: "3",
    name: "WhatsApp",
    description: "Penjualan langsung via WhatsApp",
    status: true,
  },
  {
    id: "4",
    name: "Instagram",
    description: "Penjualan via Instagram Shop",
    status: false,
  },
  {
    id: "5",
    name: "Website",
    description: "Penjualan melalui website resmi",
    status: true,
  },
];

interface ChannelCardProps {
  channel: SalesChannel;
  index: number;
  onView: (channel: SalesChannel) => void;
  onEdit: (channel: SalesChannel) => void;
  onDelete: (channelId: string) => void;
}

const getChannelIcon = (name: string) => {
  const lower = name.toLowerCase();
  if (
    lower.includes("shopee") ||
    lower.includes("tokopedia") ||
    lower.includes("lazada")
  ) {
    return ShoppingBag;
  }
  if (lower.includes("whatsapp")) return MessageCircle;
  if (lower.includes("instagram")) return Instagram;
  if (lower.includes("website")) return Globe;
  return Store;
};

const channelColors: Record<
  string,
  { bg: string; text: string; border: string }
> = {
  shopee: {
    bg: "bg-orange/10",
    text: "text-orange",
    border: "border-l-orange",
  },
  tokopedia: {
    bg: "bg-success/10",
    text: "text-success",
    border: "border-l-success",
  },
  whatsapp: {
    bg: "bg-success/10",
    text: "text-success",
    border: "border-l-success",
  },
  instagram: { bg: "bg-pink/10", text: "text-pink", border: "border-l-pink" },
  lazada: { bg: "bg-info/10", text: "text-info", border: "border-l-info" },
  website: {
    bg: "bg-purple/10",
    text: "text-purple",
    border: "border-l-purple",
  },
  default: {
    bg: "bg-primary/10",
    text: "text-primary",
    border: "border-l-primary",
  },
};

const getChannelColor = (name: string) => {
  const lower = name.toLowerCase();
  for (const key of Object.keys(channelColors)) {
    if (lower.includes(key)) return channelColors[key];
  }
  return channelColors.default;
};

const ChannelCard = memo(function ChannelCard({
  channel,
  index,
  onView,
  onEdit,
  onDelete,
}: ChannelCardProps) {
  const Icon = getChannelIcon(channel.name);
  const colorScheme = getChannelColor(channel.name);

  return (
    <Card
      className={`border-l-4 ${colorScheme.border} animate-fade-in card-hover`}
      style={{ animationDelay: `${index * 50}ms` }}
    >
      <CardContent className="p-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div
              className={`h-12 w-12 rounded-xl ${colorScheme.bg} flex items-center justify-center`}
            >
              <Icon className={`h-6 w-6 ${colorScheme.text}`} />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <p className="font-semibold">{channel.name}</p>
                {channel.status ? (
                  <Badge variant="success" className="text-[10px]">
                    <CheckCircle className="h-3 w-3 mr-1" />
                    Aktif
                  </Badge>
                ) : (
                  <Badge variant="outline" className="text-[10px]">
                    <XCircle className="h-3 w-3 mr-1" />
                    Nonaktif
                  </Badge>
                )}
              </div>
              <p className="text-sm text-muted-foreground mt-1">
                {channel.description || "Tidak ada deskripsi"}
              </p>
            </div>
          </div>

          <div className="flex items-center gap-1">
            <IconButton color="info" size="sm" onClick={() => onView(channel)}>
              <Eye className="h-4 w-4" />
            </IconButton>
            <IconButton
              color="warning"
              size="sm"
              onClick={() => onEdit(channel)}
            >
              <Edit className="h-4 w-4" />
            </IconButton>
            <IconButton
              color="destructive"
              size="sm"
              onClick={() => onDelete(channel.id)}
            >
              <Trash2 className="h-4 w-4" />
            </IconButton>
          </div>
        </div>
      </CardContent>
    </Card>
  );
});

export default function SalesChannelPage() {
  const router = useRouter();
  const [channels] = useState<SalesChannel[]>(mockSalesChannels);

  const handleEdit = (channel: SalesChannel) => {
    router.push(`/settings/sales-channels/${channel.id}`);
  };

  const handleDelete = (channelId: string) => {
    console.log("Delete channel:", channelId);
  };

  const handleView = (channel: SalesChannel) => {
    router.push(`/settings/sales-channels/${channel.id}`);
  };

  return (
    <div className="space-y-6">
      {/* Page Header */}
      <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
        <div>
          <h1 className="page-title flex items-center gap-2">
            <Store className="h-7 w-7 text-cyan" />
            Sales Channels
          </h1>
          <p className="page-description">
            Kelola semua channel penjualan Anda
          </p>
        </div>

        <Link href="/settings/sales-channels/add">
          <Button variant="gradient">
            <Plus className="mr-2 h-4 w-4" />
            Tambah Channel
          </Button>
        </Link>
      </div>

      {/* Channel Cards */}
      <div className="grid gap-4 sm:grid-cols-2">
        {channels.length === 0 ? (
          <Card className="sm:col-span-2 p-8">
            <div className="text-center py-12">
              <div className="h-16 w-16 rounded-2xl bg-cyan/10 flex items-center justify-center mx-auto mb-4">
                <Store className="h-8 w-8 text-cyan" />
              </div>
              <p className="text-base font-semibold">Belum ada sales channel</p>
              <p className="text-sm text-muted-foreground mt-1">
                Tambahkan channel penjualan untuk mengelola order
              </p>
            </div>
          </Card>
        ) : (
          channels.map((channel, index) => (
            <ChannelCard
              key={channel.id}
              channel={channel}
              index={index}
              onView={handleView}
              onEdit={handleEdit}
              onDelete={handleDelete}
            />
          ))
        )}
      </div>
    </div>
  );
}

