'use client';

import { useEffect, useMemo } from "react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Plus, Trash2 } from "lucide-react";
import { useForm, useFieldArray } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { orderSchema, OrderFormValues } from "@/schemas/zod.schemas";
import { FormField } from "../field/FormField";

export function OrderForm() {
  // ≡ƒö╣ Form utama
  const {
    register,
    control,
    handleSubmit,
    setValue,
    watch,
    formState: { errors },
  } = useForm<OrderFormValues>({
    resolver: zodResolver(orderSchema),
    defaultValues: {
      orderNumber: "",
      date: new Date().toISOString().split("T")[0],
      salesChannel: "",
      paymentStatus: "belum_dibayar",
      discount: 0,
      insurance: 0,
      shippingCost: 0,
      weight: 0,
      note: "",
      products: [
        { name: "", variant: "", quantity: 1, price: 0, weight: 0, total: 0 },
      ],
      subtotal: 0,
      total: 0,
    },
  });

  // ≡ƒö╣ Field array untuk products
  const { fields: products, append, remove } = useFieldArray({
    control,
    name: "products",
  });

  const watchProducts = watch("products");
  const discount = watch("discount") || 0;
  const insurance = watch("insurance") || 0;
  const shippingCost = watch("shippingCost") || 0;

  // ≡ƒö╣ Auto-update total tiap perubahan quantity/price
  useEffect(() => {
    watchProducts.forEach((p, i) => {
      const total = (p.quantity || 0) * (p.price || 0);
      if (total !== p.total) {
        setValue(`products.${i}.total`, total);
      }
    });
  }, [watchProducts, setValue]);


  const calculateSubtotal = () => watchProducts.reduce((sum, p) => sum + (p.total || 0), 0);

  const calculateTotal = () => {
    return calculateSubtotal() - discount + insurance + shippingCost;
  };
  

  const addProduct = () => {
    append({ name: "", variant: "", quantity: 1, price: 0, weight: 0, total: 0 });
  };

  const onFormSubmit = (data: OrderFormValues) => {
    const finalData = {
      ...data,
      subtotal: calculateSubtotal(),
      total: calculateTotal(),
    };
    console.log("Final Order Data:", finalData);
  };

  return (
    <form onSubmit={handleSubmit(onFormSubmit)} className="space-y-6">
      {/* Informasi Order */}
      <Card>
        <CardHeader>
          <CardTitle>Informasi Order</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4 grid gap-4 md:grid-cols-2">
          <FormField<OrderFormValues>
            label="No Order"
            name="orderNumber"
            register={register}
            placeholder="AUTO-GENERATE"
            type="text"
          />

          <FormField<OrderFormValues>
            label="Tanggal"
            name="date"
            register={register}
            type="date"
            error={errors.date?.message}
          />

          <div className="space-y-2">
            <label className="text-sm font-medium">Sales Channel *</label>
            <select {...register("salesChannel")} className="w-full h-10 rounded-lg border border-input bg-background px-3 text-sm">
              <option value="">Pilih Sales Channel</option>
              <option value="Shopee">Shopee</option>
              <option value="Tokopedia">Tokopedia</option>
              <option value="WhatsApp">WhatsApp</option>
              <option value="Instagram">Instagram</option>
            </select>
            {errors.salesChannel && <span className="text-xs text-red-500">{errors.salesChannel.message}</span>}
          </div>

          <div className="space-y-2">
            <label className="text-sm font-medium">Status Pembayaran</label>
            <select {...register("paymentStatus")} className="w-full h-10 rounded-lg border border-input bg-background px-3 text-sm">
              <option value="belum_dibayar">Belum Dibayar</option>
              <option value="cicilan">Cicilan</option>
              <option value="lunas">Lunas</option>
              <option value="dibatalkan">Dibatalkan</option>
            </select>
          </div>
        </CardContent>
      </Card>

      <Card>
        <CardHeader className="flex flex-row items-center justify-between">
          <CardTitle>Produk</CardTitle>
          <Button type="button" onClick={addProduct} size="sm">
            <Plus className="mr-2 h-4 w-4" /> Tambah Produk
          </Button>
        </CardHeader>
        <CardContent className="space-y-4">
          {products.map((product, index) => (
            <div key={product.id} className="rounded-lg border p-4 space-y-4">
              <div className="flex items-center justify-between mb-2">
                <span className="font-medium">Produk {index + 1}</span>
                {products.length > 1 && (
                  <Button type="button" variant="ghost" size="sm" onClick={() => remove(index)}>
                    <Trash2 className="h-4 w-4 text-destructive" />
                  </Button>
                )}
              </div>

              <div className="grid grid-cols-10 gap-4 items-start">
                <div className="col-span-12 md:col-span-3 flex flex-col">
                  <FormField<OrderFormValues>
                    label="Nama Produk"
                    name={`products.${index}.name`}
                    register={register}
                    error={errors.products?.[index]?.name?.message}
                  />
                </div>

                <div className="col-span-12 md:col-span-2 flex flex-col">
                  <FormField<OrderFormValues>
                    label="Variant"
                    name={`products.${index}.variant`}
                    register={register}
                    error={errors.products?.[index]?.variant?.message}
                  />
                </div>

                <div className="col-span-12 md:col-span-1 flex flex-col">
                  <FormField<OrderFormValues>
                    label="Qty"
                    name={`products.${index}.quantity`}
                    register={register}
                    type="number"
                    error={errors.products?.[index]?.quantity?.message}
                  />
                </div>

                <div className="col-span-12 md:col-span-2 flex flex-col">
                  <FormField<OrderFormValues>
                    label="Harga"
                    name={`products.${index}.price`}
                    register={register}
                    type="number"
                    error={errors.products?.[index]?.price?.message}
                  />
                </div>

                <div className="col-span-12 md:col-span-2 flex flex-col">
                  <FormField<OrderFormValues>
                    label="Total"
                    name={`products.${index}.total`}
                    register={register}
                    type="number"
                    nullable
                    error={errors.products?.[index]?.total?.message}
                  />
                </div>
              </div>
            </div>
          ))}
        </CardContent>
      </Card>


      {/* Biaya & Total */}
      <Card>
        <CardHeader>
          <CardTitle>Perhitungan</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="flex justify-between text-lg font-bold border-t pt-2">
            <span>Total:</span>
            <span className="text-primary">Rp {calculateTotal().toLocaleString("id-ID")}</span>
          </div>
        </CardContent>
      </Card>

      {/* Catatan */}
      <Card>
        <CardHeader>
          <CardTitle>Catatan</CardTitle>
        </CardHeader>
        <CardContent>
          <textarea
            {...register("note")}
            className="w-full min-h-25 rounded-lg border border-input bg-background px-3 py-2 text-sm"
            placeholder="Catatan tambahan..."
          />
        </CardContent>
      </Card>

      {/* Actions */}
      <div className="flex justify-end gap-4">
        <Button type="submit">Simpan Order</Button>
      </div>
    </form>
  );
}

"use client";

import { useEffect, useState, useCallback } from "react";
import { useParams, useRouter } from "next/navigation";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { ArrowLeft, Loader2, AlertCircle } from "lucide-react";

interface EditPageWrapperProps<T> {
  title: string;
  fetchData: (id: string) => Promise<T | null>;
  FormComponent: React.ComponentType<{
    initialData?: T;
    isEditMode?: boolean;
    onSuccess?: () => void;
  }>;
  redirectPath: string;
  LoadingComponent?: React.ComponentType;
  NotFoundComponent?: React.ComponentType;
}

export function EditPageWrapper<T>({
  title,
  fetchData,
  FormComponent,
  redirectPath,
  LoadingComponent,
  NotFoundComponent,
}: EditPageWrapperProps<T>) {
  const params = useParams();
  const router = useRouter();
  const id = params.id as string;

  const [data, setData] = useState<T | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const loadData = async () => {
      try {
        setLoading(true);
        setError(null);
        const result = await fetchData(id);
        setData(result);
      } catch (err) {
        setError(err instanceof Error ? err.message : "Gagal memuat data");
      } finally {
        setLoading(false);
      }
    };
    if (id) loadData();
  }, [id, fetchData]);

  const handleSuccess = useCallback(() => {
    router.push(redirectPath);
  }, [router, redirectPath]);

  const handleBack = useCallback(() => {
    router.push(redirectPath);
  }, [router, redirectPath]);

  if (loading) {
    if (LoadingComponent) return <LoadingComponent />;
    return (
      <Card>
        <CardContent className="flex items-center justify-center min-h-[400px]">
          <div className="flex flex-col items-center gap-4">
            <Loader2 className="h-10 w-10 animate-spin text-primary" />
            <p className="text-muted-foreground">Memuat data...</p>
          </div>
        </CardContent>
      </Card>
    );
  }

  if (error || !data) {
    if (NotFoundComponent) return <NotFoundComponent />;
    return (
      <Card>
        <CardContent className="flex flex-col items-center justify-center min-h-[400px] gap-4">
          <div className="h-16 w-16 rounded-2xl bg-destructive/10 flex items-center justify-center">
            <AlertCircle className="h-8 w-8 text-destructive" />
          </div>
          <div className="text-center">
            <h2 className="text-xl font-semibold mb-2">Data Tidak Ditemukan</h2>
            <p className="text-muted-foreground mb-4">
              {error ||
                "Data yang Anda cari tidak tersedia atau telah dihapus."}
            </p>
          </div>
          <Button variant="outline" onClick={handleBack} className="gap-2">
            <ArrowLeft className="h-4 w-4" />
            Kembali
          </Button>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Button
          variant="ghost"
          size="icon"
          onClick={handleBack}
          className="shrink-0 rounded-xl"
        >
          <ArrowLeft className="h-5 w-5" />
        </Button>
        <div>
          <h1 className="page-title">{title}</h1>
          <p className="text-sm text-muted-foreground">
            Edit data dan simpan perubahan
          </p>
        </div>
      </div>
      <FormComponent
        initialData={data}
        isEditMode={true}
        onSuccess={handleSuccess}
      />
    </div>
