import { v4 as uuid } from "uuid";

export function getAll<T>(key: string): T[]{
    if (typeof window === 'undefined') return [];
    return JSON.parse(localStorage.getItem(key) || "{}");
}

export function saveAll<T>(key: string, data: T[]){
    localStorage.setItem(key, JSON.stringify(data));
}

export function create<T extends {id?: string}>(key:string, item: T){
    const data = getAll<T>(key);
    const newItem = {...item, id: uuid() };
    saveAll(key, [newItem, ...data]);
    return newItem;
}

export function update<T extends {id: string}>(
    key: string,
    id: string,
    patch: Partial<T>
){
    const data = getAll<T>(key).map((item) => 
        item.id === id ? {...item, ...patch} : item
    );
    saveAll(key, data);
}

export function remove(key: string, id: string){
    const data = getAll(key).filter((item:any)=> item.id !== id);
    saveAll(key, data);
}
